const roots = selected ? [{dir: selected, source: "openclaw-extra", tier: "extra"}] : [];
const nativeWorkspace = process.env.SHIJU_OPENCLAW_NATIVE_SKILL_WORKSPACE;
if (nativeWorkspace === workspaceDir && path.isAbsolute(nativeWorkspace) && fs.realpathSync(nativeWorkspace) === nativeWorkspace) {
	const [native] = resolveWorkspaceSkillDirectories(workspaceDir, true);
	// A workspace skill root must stay inside the bound workspace.
	const metadata = fs.lstatSync(native.dir, {throwIfNoEntry: false});
	if (metadata?.isDirectory()) roots.push({...native, tier: "workspace"});
}
